mapper.select:
SELECT DISTINCT result.VALUE
FROM (SELECT DATE(start_time) AS VALUE
FROM t_groups_person
WHERE is_deleted = 0 and t_groups_person.groups_id = #{groupId}
UNION ALL
SELECT DATE(end_time) AS VALUE
FROM t_groups_person
WHERE is_deleted = 0 and t_groups_person.groups_id = #{groupId}
    ) AS result
WHERE result.
    VALUE IS NOT NULL
ORDER BY VALUE DESC;

select count(id)
from t_groups_person
where is_deleted = 0
  and groups_id = #{groupId}
  and DATE(start_time) <= #{yesterday}

SELECT
(SELECT COUNT(*) FROM t_groups_person WHERE groups_id = #{groupId} and is_deleted = 0 and start_time IS NOT NULL and DATE(start_time) <= #{currentDay} ) -
(SELECT COUNT(*) FROM t_groups_person WHERE groups_id = #{groupId} and is_deleted = 0 and start_time IS NOT NULL and DATE(start_time) <= #{currentDay} and DATE(end_time) <= #{currentDay}) AS difference_count;
